  "nav.about":"About",
  "about.title":"About",
  "about.app":"App Name",
  "about.developer":"Developer",
  "about.publisher":"Publisher",
  "about.intro":"NetCheck diagnoses and repairs TOS 7 network problems. It inspects interfaces, isolates connectivity faults, checks DNS, TNAS.online, and DDNS, measures bandwidth, and keeps history so you can tell whether an issue is on the NAS, LAN, or Internet.",
  "about.modules":"Module Guide",
  "about.dashboard":"Purpose: Quickly judge the NAS network’s overall condition and confirm which device you are viewing.\nHow to use: First check the hostname, primary IP, and architecture under the heading. Then review the health score, open-issue count, and the gateway, Internet, DNS, and IPv6 lights. If something looks wrong, choose Run Check for a full diagnosis or View All to inspect detailed groups.\nTip: The score is a summary; use Diagnose results to find the actual cause.",
  "about.interfaces":"Purpose: Inspect runtime facts for every physical, OVS internal, virtual, tunnel, and Docker interface.\nHow to use: Open Interfaces from the sidebar. Check whether State is Up or Down, then review IPv4, speed, mode, and MAC. Select any row to see all interface details. If a physical port is Down, inspect the cable, switch port, or bond configuration.\nTip: Up/Down is a runtime fact, not the same as a Pass/Fail diagnosis verdict.\nThe OS loopback interface is hidden because it is internal and not a LAN/WAN path.\nLink Rate is negotiated by the NIC and represents theoretical link capability, not measured throughput. Use a bandwidth test for throughput.",
  "about.diagnose":"Purpose: Run a complete network health check and localize faults to link, IP, routing, DNS, Internet, TOS service, or transport layers.\nHow to use: Choose Run Full Check; the in-button spinner shows execution. When finished, review Pass, Warn, Fail, and N/A by groups A–I and address Fail items first. Export a report when you need evidence, and use Fix only after reading and confirming the wizard.\nTip: DNS or Internet faults can affect downstream checks; fix foundational issues first, then rescan.",
  "about.tools":"Purpose: Answer a specific question without running the entire diagnosis suite.\nHow to use: In Device Discovery, choose Scan and review IP/MAC and conflict hints. For Port Check, enter host and port, then choose Check. For Traceroute, enter a target and inspect the breakpoint. For DNS Compare, enter a domain and compare local and public answers. The page prompts for missing fields.\nTip: If a domain resolves but a port is closed, check firewall, service, and port-forwarding state.",
  "about.monitor":"Purpose: Track latency, packet loss, and alerts for intermittent slowdowns or drops.\nHow to use: Choose Sample Now for a fresh measurement, then use the 7-day or 30-day range to review average loss, RTT, maximum loss, and trends. Use Alert History to see when incidents occurred and how often. With thresholds configured, continued sampling shows whether a link is stable.\nTip: Judge intermittent faults from multiple samples rather than one ping.\nPause or resume continuous monitoring from the Monitoring header. Sample Now remains available while monitoring is paused.",
  "about.security":"Purpose: Review firewall state, listening-port exposure, higher-risk services, and the remote-access tunnel.\nHow to use: Open Security and choose Rescan for fresh data. Confirm whether the firewall is enabled, then review exposed ports and risk levels. The tunnel card shows TNAS.online state. For high-risk listeners, confirm the service is required, then adjust permissions or access sources in TOS.\nTip: Apply security advice in context; do not blindly stop required services.",
  "about.snapshots":"Purpose: Keep comparable, restorable safety points before network changes or repairs.\nHow to use: Choose Create to take a snapshot and write a recognizable note. Use Diff to inspect changes. Restore replaces the current network configuration, so verify the note, time, and differences first and make sure a management path remains available.\nTip: Create a snapshot before major changes rather than relying only on automatic ones.",
  "about.history":"Purpose: Review diagnosis and repair timelines to tell whether an issue is intermittent, persistent, or change-related.\nHow to use: Switch between diagnosis and repair history. Compare score, failure count, actions, results, and duration. If the score remains low after a repair, compare before-and-after records to see whether the cause was removed. Attach exported reports and timestamps when contacting support.\nTip: History supplements, but does not replace, a fresh scan.\nHousekeeping: Delete a single record with its Delete button, or use Clear All after confirmation. These actions do not erase the security audit log.\nEach row can download the log snapshot captured for that diagnosis or repair.",
  "about.settings":"Purpose: Control interface language, theme, and repair safety policy.\nHow to use: In Settings, choose language and theme; the interface applies them immediately. Repair mode and administrator confirmation control how higher-risk actions run. Save or refresh as needed after changes. Version and architecture are now centralized in About.\nTip: Keep administrator confirmation enabled when repair impact is uncertain.",
  "about.modulesHint":"Select a module to expand its detailed description and steps. Select it again to collapse it. Long text wraps independently.",
  "about.aboutGuide":"Review the app name, version, architecture, developer, and publisher. Start here to confirm the installed version or investigate an upgrade. Expand modules for use cases and steps.",
