  "if.up":"Aktiv",
  "if.down":"Inaktiv",
  "nav.about":"Über",
  "about.title":"Über",
  "about.app":"App-Name",
  "about.developer":"Entwickler",
  "about.publisher":"Herausgeber",
  "about.intro":"NetCheck diagnostiziert und repariert Netzwerkprobleme unter TOS 7. Es prüft Schnittstellen, grenzt Verbindungsstörungen ein, testet DNS, TNAS.online und DDNS, misst Bandbreite und speichert Verläufe. So erkennen Sie, ob ein Problem am NAS, LAN oder Internet liegt.",
  "about.modules":"Modulanleitung",
  "about.dashboard":"Fasst Gesundheitsscore, offene Probleme, Statusanzeigen und Schnittstellenhinweise zusammen, damit Sie den Gesamtzustand beurteilen und eine vollständige Diagnose starten können.\nSchritte: Modul öffnen, aktuelle Daten prüfen, Hauptaktion ausführen und Ergebnis mit dem vorherigen Stand vergleichen.",
  "about.interfaces":"Zeigt alle physischen, virtuellen, OVS- und Tunnel-Schnittstellen mit Adressen, Geschwindigkeit, Modus, MAC und weiteren Laufzeitdaten. Wählen Sie eine Zeile für Details.\nSchritte: Modul öffnen, aktuelle Daten prüfen, Hauptaktion ausführen und Ergebnis mit dem vorherigen Stand vergleichen.\nDas Loopback-Interface des Systems wird ausgeblendet, weil es intern und kein LAN-/WAN-Pfad ist.\nDie Link-Datenrate wird von der NIC ausgehandelt und beschreibt die theoretische Linkfähigkeit, nicht den gemessenen Durchsatz. Verwenden Sie für den Durchsatz einen Bandbreitentest.",
  "about.diagnose":"Führt alle Prüfungen aus und gruppiert Ergebnisse als bestanden, Warnung, Fehler oder nicht zutreffend. Exportieren Sie Berichte oder folgen Sie der geführten Reparatur.\nSchritte: Modul öffnen, aktuelle Daten prüfen, Hauptaktion ausführen und Ergebnis mit dem vorherigen Stand vergleichen.",
  "about.tools":"Bietet Geräteerkennung, Portprüfungen, traceroute und DNS-Vergleich, um Erreichbarkeit zu testen, Abbruchpunkte zu finden und Abweichungen bei der Auflösung zu untersuchen.\nSchritte: Modul öffnen, aktuelle Daten prüfen, Hauptaktion ausführen und Ergebnis mit dem vorherigen Stand vergleichen.",
  "about.monitor":"Misst Gateway-Latenz und Paketverlust wiederholt, speichert Trends und Alarme. Hilfreich bei zeitweiligen Verlangsamungen und instabilen Verbindungen.\nSchritte: Modul öffnen, aktuelle Daten prüfen, Hauptaktion ausführen und Ergebnis mit dem vorherigen Stand vergleichen.\nPausieren oder setzen Sie die kontinuierliche Überwachung in der Kopfzeile der Überwachung fort. „Jetzt messen“ bleibt auch bei pausierter Überwachung verfügbar.",
  "about.security":"Prüft Firewall-Status, offengelegte Listen-Ports und riskantere Dienste und zeigt den Remote-Tunnelstatus, damit Sie die Angriffsfläche bewerten können.\nSchritte: Modul öffnen, aktuelle Daten prüfen, Hauptaktion ausführen und Ergebnis mit dem vorherigen Stand vergleichen.",
  "about.snapshots":"Speichert Netzwerkkonfigurations-Snapshots, vergleicht Unterschiede und unterstützt Rollbacks vor oder nach Reparaturen als Sicherheitsnetz für Änderungen.\nSchritte: Modul öffnen, aktuelle Daten prüfen, Hauptaktion ausführen und Ergebnis mit dem vorherigen Stand vergleichen.",
  "about.history":"Zentralisiert Diagnose- und Reparaturberichte, damit Sie Scoreveränderungen, Fehler, ausgeführte Aktionen und Dauer später nachvollziehen können.\nSchritte: Modul öffnen, aktuelle Daten prüfen, Hauptaktion ausführen und Ergebnis mit dem vorherigen Stand vergleichen.\nVerwaltung: Entfernen Sie einen einzelnen Eintrag über „Löschen“, oder verwenden Sie nach Bestätigung „Alle löschen“. Diese Aktionen entfernen nicht das Sicherheitsprotokoll.\nFür jede Zeile können Sie den damals gespeicherten Diagnose- oder Reparaturverlauf herunterladen.",
  "about.settings":"Konfiguriert Sprache, Design, Reparaturberechtigungen, geplante Prüfungen und zugehörige Einstellungen. Die Über-Seite zeigt Versions- und Entwicklungsinformationen.\nSchritte: Modul öffnen, aktuelle Daten prüfen, Hauptaktion ausführen und Ergebnis mit dem vorherigen Stand vergleichen.",
  "about.modulesHint":"Wähle ein Modul, um Beschreibung und Schritte zu erweitern. Erneut auswählen reduziert es. Lange Texte brechen unabhängig um.",
  "about.aboutGuide":"Prüfen Sie App-Name, Version, Architektur, Entwickler und Herausgeber. Beginnen Sie hier, um die installierte Version zu bestätigen oder ein Upgrade zu prüfen. Klappen Sie Module für Anwendungsfälle und Schritte auf.",
  "fix.dnsServers":"DNS-Server (kommagetrennt)",
