  "nav.about":"À propos",
  "about.title":"À propos",
  "about.app":"Nom de l’app",
  "about.developer":"Développeur",
  "about.publisher":"Éditeur",
  "about.intro":"NetCheck diagnostique et répare les problèmes réseau de TOS 7. Il inspecte les interfaces, isole les pannes de connectivité, vérifie DNS, TNAS.online et DDNS, mesure la bande passante et conserve l’historique pour situer un incident sur le NAS, le LAN ou Internet.",
  "about.modules":"Guide des modules",
  "about.dashboard":"Résume le score de santé, les problèmes ouverts, les voyants et les points clés des interfaces afin d’évaluer l’état général du réseau et de lancer un diagnostic complet.\nÉtapes : ouvrez le module, vérifiez les données actuelles, exécutez l’action principale, puis comparez avec l’état précédent.",
  "about.interfaces":"Liste toutes les interfaces physiques, virtuelles, OVS et tunnels avec adresses, vitesse, mode, MAC et autres faits d’exécution. Sélectionnez une ligne pour les détails.\nÉtapes : ouvrez le module, vérifiez les données actuelles, exécutez l’action principale, puis comparez avec l’état précédent.\nL’interface loopback du système est masquée : elle est interne et ne constitue pas un chemin LAN/WAN.\nLe débit de liaison est négocié par la carte réseau et représente une capacité théorique, pas un débit mesuré. Utilisez un test de bande passante pour le débit réel.",
  "about.diagnose":"Exécute la suite complète de contrôles et regroupe les résultats : réussite, avertissement, échec ou non applicable. Exportez un rapport ou suivez la réparation guidée.\nÉtapes : ouvrez le module, vérifiez les données actuelles, exécutez l’action principale, puis comparez avec l’état précédent.",
  "about.tools":"Fournit découverte d’appareils, tests de ports, traceroute et comparaison DNS pour vérifier l’accessibilité, localiser les ruptures et analyser les différences de résolution.\nÉtapes : ouvrez le module, vérifiez les données actuelles, exécutez l’action principale, puis comparez avec l’état précédent.",
  "about.monitor":"Échantillonne régulièrement latence et perte de paquets de la passerelle, conserve tendances et alertes. Utile pour ralentissements intermittents et liens instables.\nÉtapes : ouvrez le module, vérifiez les données actuelles, exécutez l’action principale, puis comparez avec l’état précédent.\nSuspendez ou reprenez la surveillance continue depuis l’en-tête Surveillance. « Mesurer maintenant » reste disponible pendant la suspension.",
  "about.security":"Vérifie le pare-feu, l’exposition des ports en écoute et les services plus risqués, et affiche l’état du tunnel distant pour examiner la surface d’attaque.\nÉtapes : ouvrez le module, vérifiez les données actuelles, exécutez l’action principale, puis comparez avec l’état précédent.",
  "about.snapshots":"Enregistre des instantanés de configuration réseau, compare les différences et permet un rollback avant ou après réparation comme filet de sécurité.\nÉtapes : ouvrez le module, vérifiez les données actuelles, exécutez l’action principale, puis comparez avec l’état précédent.",
  "about.history":"Centralise les historiques de diagnostic et de réparation pour suivre évolution du score, échecs, actions exécutées et durées lors du bilan.\nÉtapes : ouvrez le module, vérifiez les données actuelles, exécutez l’action principale, puis comparez avec l’état précédent.\nGestion : supprimez un enregistrement avec « Supprimer », ou utilisez « Tout effacer » après confirmation. Ces actions n’effacent pas le journal de sécurité.\nChaque ligne permet de télécharger le journal de diagnostic ou de réparation conservé à ce moment.",
  "about.settings":"Configure langue, thème, autorisations de réparation, contrôles planifiés et préférences associées. La page À propos affiche version et informations de développement.\nÉtapes : ouvrez le module, vérifiez les données actuelles, exécutez l’action principale, puis comparez avec l’état précédent.",
  "about.modulesHint":"Sélectionnez un module pour afficher sa description détaillée et ses étapes. Resélectionnez-le pour le réduire. Les textes longs passent à la ligne indépendamment.",
  "about.aboutGuide":"Consultez le nom, la version, l’architecture, le développeur et l’éditeur de l’application. Commencez ici pour confirmer la version installée ou examiner une mise à niveau. Dépliez les modules pour les cas d’usage et les étapes.",
  "fix.dnsServers":"Serveurs DNS (séparés par des virgules)",
  "fix.gateway":"Adresse de passerelle",
  "fix.dnsRequired":"Saisissez au moins un serveur DNS",
  "fix.gatewayRequired":"Saisissez l’adresse de la passerelle",
