  "about.intro":"NetCheck diagnostica y repara problemas de red en TOS 7. Inspecciona interfaces, aísla fallos de conectividad, comprueba DNS, TNAS.online y DDNS, mide el ancho de banda y guarda historiales para saber si el problema está en el NAS, la LAN o Internet.",
  "about.modules":"Guía de módulos",
  "about.dashboard":"Resume la puntuación de salud, problemas abiertos, luces de estado y datos clave de interfaces para valorar el estado general de la red e iniciar un diagnóstico completo.\nPasos: abre el módulo, revisa los datos actuales, ejecuta la acción principal y compara con el estado anterior.",
  "about.interfaces":"Muestra todas las interfaces físicas, virtuales, OVS y de túnel con direcciones, velocidad, modo, MAC y otros datos reales. Pulsa una fila para ver detalles.\nPasos: abre el módulo, revisa los datos actuales, ejecuta la acción principal y compara con el estado anterior.\nLa interfaz loopback del sistema se oculta porque es interna y no es una ruta LAN/WAN.\nLa velocidad de enlace la negocia la NIC y representa una capacidad teórica, no el rendimiento medido. Use una prueba de ancho de banda para medir el rendimiento.",
  "about.diagnose":"Ejecuta el conjunto completo de comprobaciones y agrupa los resultados en superado, advertencia, error o no aplicable. Exporta informes o sigue la reparación guiada.\nPasos: abre el módulo, revisa los datos actuales, ejecuta la acción principal y compara con el estado anterior.",
  "about.tools":"Ofrece descubrimiento de dispositivos, prueba de puertos, traceroute y comparación de DNS para verificar accesibilidad, localizar cortes y analizar diferencias de resolución.\nPasos: abre el módulo, revisa los datos actuales, ejecuta la acción principal y compara con el estado anterior.",
  "about.monitor":"Muestrea periódicamente latencia y pérdida de paquetes del gateway, guarda tendencias y alertas. Útil para ralentizaciones intermitentes y enlaces inestables.\nPasos: abre el módulo, revisa los datos actuales, ejecuta la acción principal y compara con el estado anterior.\nPause o reanude la supervisión continua desde la cabecera de Supervisión. «Medir ahora» sigue disponible mientras la supervisión está en pausa.",
  "about.security":"Comprueba el cortafuegos, la exposición de puertos en escucha y servicios de mayor riesgo, y muestra el estado del túnel remoto para revisar la superficie de ataque.\nPasos: abre el módulo, revisa los datos actuales, ejecuta la acción principal y compara con el estado anterior.",
  "about.snapshots":"Guarda instantáneas de configuración de red, compara diferencias y permite revertir antes o después de una reparación como red de seguridad.\nPasos: abre el módulo, revisa los datos actuales, ejecuta la acción principal y compara con el estado anterior.",
  "about.history":"Centraliza historiales de diagnóstico y reparación para seguir cambios de puntuación, fallos, acciones ejecutadas y duración en las revisiones.\nPasos: abre el módulo, revisa los datos actuales, ejecuta la acción principal y compara con el estado anterior.\nMantenimiento: elimine un registro con “Eliminar” o use “Borrar todo” tras confirmarlo. Estas acciones no borran el registro de seguridad.\nCada fila permite descargar el registro de diagnóstico o reparación guardado en ese momento.",
  "about.settings":"Configura idioma, tema, permisos de reparación, comprobaciones programadas y preferencias relacionadas. La página Acerca de muestra versión e información de desarrollo.\nPasos: abre el módulo, revisa los datos actuales, ejecuta la acción principal y compara con el estado anterior.",
  "about.modulesHint":"Selecciona un módulo para expandir su descripción y pasos. Selecciónalo de nuevo para contraerlo. El texto largo se ajusta de forma independiente.",
  "about.aboutGuide":"Consulte el nombre, la versión, la arquitectura, el desarrollador y el editor de la app. Empiece aquí para confirmar la versión instalada o investigar una actualización. Expanda los módulos para ver casos de uso y pasos.",
