  "nav.about":"Informazioni",
  "about.title":"Informazioni",
  "about.app":"Nome app",
  "about.developer":"Sviluppatore",
  "about.publisher":"Editore",
  "about.intro":"NetCheck diagnostica e ripara i problemi di rete di TOS 7. Ispeziona le interfacce, isola i guasti di connettività, verifica DNS, TNAS.online e DDNS, misura la banda e conserva lo storico per capire se il problema è nel NAS, nella LAN o in Internet.",
  "about.modules":"Guida dei moduli",
  "about.dashboard":"Riepiloga punteggio di salute, problemi aperti, spie e evidenze delle interfacce, utile per valutare la rete e avviare una diagnosi completa.\nPassi: apri il modulo, controlla i dati attuali, esegui l’azione principale e confronta lo stato precedente.",
  "about.interfaces":"Elenca tutte le interfacce fisiche, virtuali, OVS e tunnel con indirizzi, velocità, modalità, MAC e altri dati reali. Seleziona una riga per i dettagli.\nPassi: apri il modulo, controlla i dati attuali, esegui l’azione principale e confronta lo stato precedente.\nL'interfaccia loopback di sistema è nascosta perché è interna e non è un percorso LAN/WAN.\nLa velocità di collegamento è negoziata dalla NIC e rappresenta una capacità teorica, non la velocità effettiva misurata. Per la velocità effettiva usare un test della larghezza di banda.",
  "about.diagnose":"Esegue la suite completa e raggruppa i risultati come superato, avviso, errore o non applicabile. Esporta un report o segui la riparazione guidata.\nPassi: apri il modulo, controlla i dati attuali, esegui l’azione principale e confronta lo stato precedente.",
  "about.tools":"Offre scoperta dispositivi, test porte, traceroute e confronto DNS per verificare raggiungibilità, individuare interruzioni ed esaminare differenze di risoluzione.\nPassi: apri il modulo, controlla i dati attuali, esegui l’azione principale e confronta lo stato precedente.",
  "about.monitor":"Campiona nel tempo latenza e perdita pacchetti del gateway, salvando tendenze e avvisi. Utile per rallentamenti intermittenti e collegamenti instabili.\nPassi: apri il modulo, controlla i dati attuali, esegui l’azione principale e confronta lo stato precedente.\nSospendi o riprendi il monitoraggio continuo dall’intestazione Monitoraggio. «Misura ora» resta disponibile quando il monitoraggio è sospeso.",
  "about.security":"Controlla firewall, porte in ascolto esposte e servizi più rischiosi, e mostra lo stato del tunnel remoto per esaminare la superficie d’attacco.\nPassi: apri il modulo, controlla i dati attuali, esegui l’azione principale e confronta lo stato precedente.",
  "about.snapshots":"Salva snapshot della configurazione di rete, confronta le differenze e supporta il rollback prima o dopo le riparazioni come rete di sicurezza.\nPassi: apri il modulo, controlla i dati attuali, esegui l’azione principale e confronta lo stato precedente.",
  "about.history":"Centralizza cronologia di diagnosi e riparazioni per seguire variazioni del punteggio, guasti, azioni eseguite e durate nelle analisi successive.\nPassi: apri il modulo, controlla i dati attuali, esegui l’azione principale e confronta lo stato precedente.\nGestione: rimuovi un singolo record con “Elimina” oppure usa “Svuota tutto” dopo la conferma. Queste azioni non eliminano il log di sicurezza.\nOgni riga consente di scaricare il log di diagnostica o riparazione conservato in quel momento.",
  "about.settings":"Configura lingua, tema, permessi di riparazione, controlli pianificati e preferenze correlate. La pagina Informazioni mostra versione e dati di sviluppo.\nPassi: apri il modulo, controlla i dati attuali, esegui l’azione principale e confronta lo stato precedente.",
  "about.modulesHint":"Seleziona un modulo per espandere descrizione e passaggi. Selezionalo di nuovo per comprimerlo. I testi lunghi vanno a capo in modo indipendente.",
  "about.aboutGuide":"Controlla nome, versione, architettura, sviluppatore ed editore dell’app. Inizia qui per confermare la versione installata o esaminare un aggiornamento. Espandi i moduli per casi d’uso e passaggi.",
