  "nav.about":"Hakkında",
  "about.title":"Hakkında",
  "about.app":"Uygulama adı",
  "about.developer":"Geliştirici",
  "about.publisher":"Yayıncı",
  "about.intro":"NetCheck, TOS 7 ağ sorunlarını teşhis eder ve onarır. Arayüzleri inceler, bağlantı arızalarını daraltır, DNS, TNAS.online ve DDNS'i denetler, bant genişliğini ölçer ve geçmişi tutarak sorunun NAS, LAN yoksa İnternet tarafında olduğunu anlamanıza yardım eder.",
  "about.modules":"Modül kılavuzu",
  "about.dashboard":"Sağlık puanını, açık sorunları, durum ışıklarını ve arayüz özetlerini birleştirir; genel ağ durumunu değerlendirip tam teşhis başlatmanızı sağlar.\nAdımlar: modülü açın, güncel verileri inceleyin, ana eylemi çalıştırın ve önceki duruma göre karşılaştırın.",
  "about.interfaces":"Fiziksel, sanal, OVS ve tünel arayüzlerinin adres, hız, mod, MAC ve diğer çalışma verileriyle listeler. Ayrıntılar için bir satır seçin.\nAdımlar: modülü açın, güncel verileri inceleyin, ana eylemi çalıştırın ve önceki duruma göre karşılaştırın.\nSistem loopback arayüzü gizlidir çünkü dahilidir ve bir LAN/WAN yolu değildir.\nBağlantı hızı NIC tarafından görüşülür ve teorik bağlantı kapasitesini gösterir; ölçülen aktarım hızı değildir. Aktarım hızı için bant genişliği testini kullanın.",
  "about.diagnose":"Tüm kontrol takımını çalıştırır ve sonuçları geçti, uyarı, hata veya uygun değil olarak gruplar. Rapor dışa aktarabilir veya destekli onarımı izleyebilirsiniz.\nAdımlar: modülü açın, güncel verileri inceleyin, ana eylemi çalıştırın ve önceki duruma göre karşılaştırın.",
  "about.tools":"Cihaz keşfi, bağlantı noktası testleri, traceroute ve DNS karşılaştırması sunar; erişilebilirliği doğrular, kopma noktalarını ve çözümleme farklarını inceler.\nAdımlar: modülü açın, güncel verileri inceleyin, ana eylemi çalıştırın ve önceki duruma göre karşılaştırın.",
  "about.monitor":"Ağ geçidi gecikmesini ve paket kaybını düzenle örnekler, eğilim ve uyarıları saklar. Aralıklı yavaşlama ile dengesiz bağlantılar için yararlıdır.\nAdımlar: modülü açın, güncel verileri inceleyin, ana eylemi çalıştırın ve önceki duruma göre karşılaştırın.\nSürekli izlemeyi İzleme başlığından duraklatın veya sürdürün. İzleme duraklatıldığında “Şimdi ölç” kullanılabilir kalır.",
  "about.security":"Güvenlik duvarını, dinlenen bağlantı noktalarının açıklığını ve yüksek riskli hizmetleri denetler; uzak tünel durumunu göstererek saldırı yüzeyini değerlendirmenize yardım eder.\nAdımlar: modülü açın, güncel verileri inceleyin, ana eylemi çalıştırın ve önceki duruma göre karşılaştırın.",
  "about.snapshots":"Ağ yapılandırma anlık görüntülerini kaydeder, farkları karşılaştırır ve onarım öncesi veya sonrası geri alma sağlayarak değişiklikler için güvenlik ağı sunar.\nAdımlar: modülü açın, güncel verileri inceleyin, ana eylemi çalıştırın ve önceki duruma göre karşılaştırın.",
  "about.history":"Teşhis ve onarım kayıtlarını merkezileştirir; puan değişimlerini, hataları, yapılan işlemleri ve süreleri sonradan incelemek için takip eder.\nAdımlar: modülü açın, güncel verileri inceleyin, ana eylemi çalıştırın ve önceki duruma göre karşılaştırın.\nYönetim: Tek bir kaydı “Sil” ile kaldırın veya onayladıktan sonra “Tümünü Temizle”yi kullanın. Bu işlemler güvenlik denetim günlüğünü silmez.\nHer satır, o anda saklanan tanılama veya onarım günlüğünü indirmenizi sağlar.",
  "about.settings":"Dili, temayı, onarım izinlerini, planlanan kontrolleri ve ilgili tercihleri ayarlar. Hakkında sayfası sürüm ve geliştirme bilgilerini gösterir.\nAdımlar: modülü açın, güncel verileri inceleyin, ana eylemi çalıştırın ve önceki duruma göre karşılaştırın.",
  "about.modulesHint":"Ayrıntılı açıklamayı ve adımları genişletmek için bir modül seçin. Daraltmak için yeniden seçin. Uzun metinler bağımsız sarılır.",
  "about.aboutGuide":"Uygulama adını, sürümü, mimariyi, geliştiriciyi ve yayıncıyı inceleyin. Yüklü sürümü doğrularken veya yükseltmeyi araştırırken buradan başlayın. Kullanım senaryoları ve adımlar için modülleri genişletin.",
  "fix.dnsServers":"DNS sunucuları (virgülle ayrılmış)",
