  "nav.about":"Sobre",
  "about.title":"Sobre",
  "about.app":"Nome da app",
  "about.developer":"Programador",
  "about.publisher":"Editor",
  "about.intro":"O NetCheck diagnostica e repara problemas de rede no TOS 7. Inspeciona interfaces, isola falhas de conectividade, verifica DNS, TNAS.online e DDNS, mede largura de banda e mantém histórico para identificar se o problema está no NAS, na LAN ou na Internet.",
  "about.modules":"Guia de módulos",
  "about.dashboard":"Resume a pontuação de saúde, problemas abertos, luzes de estado e destaques de interfaces para avaliar a rede e iniciar um diagnóstico completo.\nPassos: abra o módulo, verifique os dados atuais, execute a ação principal e compare com o estado anterior.",
  "about.interfaces":"Lista todas as interfaces físicas, virtuais, OVS e túnel com endereços, velocidade, modo, MAC e outros dados reais. Selecione uma linha para detalhes.\nPassos: abra o módulo, verifique os dados atuais, execute a ação principal e compare com o estado anterior.\nA interface loopback do sistema está oculta porque é interna e não é um caminho LAN/WAN.\nA taxa de ligação é negociada pela NIC e representa uma capacidade teórica, não a produção medida. Use um teste de largura de banda para a produção real.",
  "about.diagnose":"Executa o conjunto completo de verificações e agrupa resultados como aprovado, aviso, falha ou não aplicável. Exporte relatórios ou siga a reparação guiada.\nPassos: abra o módulo, verifique os dados atuais, execute a ação principal e compare com o estado anterior.",
  "about.tools":"Oferece descoberta de dispositivos, testes de portas, traceroute e comparação de DNS para verificar acessibilidade, localizar cortes e analisar diferenças de resolução.\nPassos: abra o módulo, verifique os dados atuais, execute a ação principal e compare com o estado anterior.",
  "about.monitor":"Amostra periodicamente latência e perda de pacotes do gateway e guarda tendências e alertas. Útil para abrandamentos intermitentes e ligações instáveis.\nPassos: abra o módulo, verifique os dados atuais, execute a ação principal e compare com o estado anterior.\nPause ou retome a monitorização contínua no cabeçalho Monitorização. «Medir agora» continua disponível com a monitorização em pausa.",
  "about.security":"Verifica firewall, exposição de portas à escuta e serviços de maior risco, e mostra o estado do túnel remoto para rever a superfície de ataque.\nPassos: abra o módulo, verifique os dados atuais, execute a ação principal e compare com o estado anterior.",
  "about.snapshots":"Guarda instantâneos de configuração de rede, compara diferenças e permite reverter antes ou depois de reparações como rede de segurança.\nPassos: abra o módulo, verifique os dados atuais, execute a ação principal e compare com o estado anterior.",
  "about.history":"Centraliza histórico de diagnósticos e reparações para acompanhar mudanças de pontuação, falhas, ações executadas e durações em revisões.\nPassos: abra o módulo, verifique os dados atuais, execute a ação principal e compare com o estado anterior.\nGestão: remova um registo com “Eliminar” ou use “Limpar Tudo” após confirmar. Estas ações não apagam o registo de segurança.\nCada linha permite descarregar o registo de diagnóstico ou reparação guardado nesse momento.",
  "about.settings":"Configura idioma, tema, permissões de reparação, verificações agendadas e preferências relacionadas. A página Sobre mostra versão e informações de desenvolvimento.\nPassos: abra o módulo, verifique os dados atuais, execute a ação principal e compare com o estado anterior.",
  "about.modulesHint":"Selecione um módulo para expandir a descrição e os passos. Selecione-o novamente para o fechar. O texto longo é ajustado de forma independente.",
  "about.aboutGuide":"Consulte o nome, a versão, a arquitetura, o programador e o editor da app. Comece aqui para confirmar a versão instalada ou investigar uma atualização. Expanda os módulos para casos de uso e passos.",
