  "about.title":"Névjegy",
  "about.app":"Alkalmazás neve",
  "about.developer":"Fejlesztő",
  "about.publisher":"Kiadó",
  "about.intro":"A NetCheck a TOS 7 hálózati problémáit diagnosztizálja és javítja. Megvizsgálja a csatolókat, elhatárolja a kapcsolódási hibákat, ellenőrzi a DNS-t, a TNAS.online-t és a DDNS-t, sávszélességet mér és előzményeket tart, hogy kiderüljön, a gond a NAS-on, a LAN-on vagy az interneten van-e.",
  "about.modules":"Modul útmutató",
  "about.dashboard":"Összefoglalja az állapotpontszámot, nyitott hibákat, jelzésfényeket és csatolóadatokat, így átlátható a hálózat állapota és indítható egy teljes diagnózis.\nLépések: nyissa meg a modult, ellenőrizze az aktuális adatokat, futtassa a fő műveletet, majd hasonlítsa össze az előző állapottal.",
  "about.interfaces":"Az összes fizikai, virtuális, OVS- és alagútfelületet listázza címekkel, sebességgel, móddal, MAC-címmel és más futási adatokkal. A részletekhez válasszon sort.\nLépések: nyissa meg a modult, ellenőrizze az aktuális adatokat, futtassa a fő műveletet, majd hasonlítsa össze az előző állapottal.\nA rendszer loopback interfésze rejtett, mert belső, nem LAN/WAN-os útvonal.\nA kapcsolati sebességet a NIC egyezi meg, és elméleti kapcsolati képességet jelöl, nem mért átviteli sebességet. Átviteli sebességhez használjon sávszélesség-tesztet.",
  "about.diagnose":"Lefuttatja a teljes ellenőrzéssort és csoportosítja az eredményeket: sikeres, figyelmeztetés, hiba vagy nem alkalmazható. Jelentést exportálhat vagy követheti az irányított javítást.\nLépések: nyissa meg a modult, ellenőrizze az aktuális adatokat, futtassa a fő műveletet, majd hasonlítsa össze az előző állapottal.",
  "about.tools":"Eszközfelderítést, portvizsgálatot, traceroute-t és DNS-összehasonlítást nyújt a elérhetőség ellenőrzésére, töréspontok keresésére és feloldási eltérések elemzésére.\nLépések: nyissa meg a modult, ellenőrizze az aktuális adatokat, futtassa a fő műveletet, majd hasonlítsa össze az előző állapottal.",
  "about.monitor":"Időszakosan méri az átjáró késleltetését és csomagvesztését, trendeket és riasztásokat tárol. Szaggatott lassulásokhoz és instabil kapcsolatokhoz hasznos.\nLépések: nyissa meg a modult, ellenőrizze az aktuális adatokat, futtassa a fő műveletet, majd hasonlítsa össze az előző állapottal.\nA folyamatos monitorozást a Monitorozás fejlécéből szüneteltetheti vagy folytathatja. Szünet alatt a „Mérés most” is elérhető marad.",
  "about.security":"Ellenőrzi a tűzfalat, a figyelt portok kitettségét és a kockázatosabb szolgáltatásokat, valamint megjeleníti a távoli alagút állapotát a támadási felület értékeléséhez.\nLépések: nyissa meg a modult, ellenőrizze az aktuális adatokat, futtassa a fő műveletet, majd hasonlítsa össze az előző állapottal.",
  "about.snapshots":"Hálózati konfigurációs pillanatképeket ment, összehasonlítja a különbségeket, és visszaállítást kínál javítás előtt vagy után, mint biztonsági háló a változtatásokhoz.\nLépések: nyissa meg a modult, ellenőrizze az aktuális adatokat, futtassa a fő műveletet, majd hasonlítsa össze az előző állapottal.",
  "about.history":"Központosítja a diagnosztikai és javítási előzményeket, így később követhetők pontszámváltozások, hibák, végrehajtott műveletek és idők.\nLépések: nyissa meg a modult, ellenőrizze az aktuális adatokat, futtassa a fő műveletet, majd hasonlítsa össze az előző állapottal.\nKarbantartás: egy bejegyzést a „Törlés” gombbal távolíthat el, vagy megerősítés után használja az „Összes törlése” funkciót. Ezek a műveletek nem törlik a biztonsági naplót.\nMinden sorból letölthető az akkor mentett diagnosztikai vagy javítási napló.",
  "about.settings":"Nyelvet, témát, javítási jogosultságokat, ütemezett ellenőrzéseket és kapcsolódó beállításokat ad meg. A Névjegy oldalon szerepel a verzió és a fejlesztői információ.\nLépések: nyissa meg a modult, ellenőrizze az aktuális adatokat, futtassa a fő műveletet, majd hasonlítsa össze az előző állapottal.",
  "about.modulesHint":"Válasszon egy modult a részletes leírás és lépések kibontásához. Újra kiválasztva összecsukható. A hosszú szöveg önállóan törik.",
  "about.aboutGuide":"Ellenőrizze az alkalmazás nevét, verzióját, architektúráját, fejlesztőjét és kiadóját. Kezdjen itt a telepített verzió ellenőrzéséhez vagy frissítés vizsgálatához. Nyissa ki a modulokat forgatókönyvekhez és lépésekhez.",
