  "nav.about":"Om",
  "about.title":"Om",
  "about.app":"Appnavn",
  "about.developer":"Utvikler",
  "about.publisher":"Utgiver",
  "about.intro":"NetCheck diagnostiserer og reparerer nettverksproblemer i TOS 7. Den undersøker grensesnitt, isolerer tilkoblingsfeil, sjekker DNS, TNAS.online og DDNS, måler båndbredde og lagrer historikk, slik at du kan se om problemet ligger på NAS-en, i LAN-et eller på internett.",
  "about.modules":"Modulveiledning",
  "about.dashboard":"Oppsummerer helsetall, åpne problemer, statuslys og grensesnittutdrag, slik at du kan vurdere nettverket og starte en fullstendig diagnose.\nTrinn: åpne modulen, kontroller nåværende data, utfør hovedhandlingen og sammenlign med forrige tilstand.",
  "about.interfaces":"Lister alle fysiske, virtuelle, OVS- og tunnelgrensesnitt med adresser, hastighet, modus, MAC og andre driftsdata. Velg en rad for detaljer.\nTrinn: åpne modulen, kontroller nåværende data, utfør hovedhandlingen og sammenlign med forrige tilstand.\nSystemets loopback-grensesnitt er skjult fordi det er internt og ikke en LAN/WAN-bane.\nKoblingshastigheten forhandles av nettverkskortet og er teoretisk kapasitet, ikke målt gjennomstrømning. Bruk en båndbredde test for gjennomstrømning.",
  "about.diagnose":"Kjører hele kontrolpakken og grupperer resultater som bestått, advarsel, feil eller ikke relevant. Eksporter en rapport eller følg guidet reparasjon.\nTrinn: åpne modulen, kontroller nåværende data, utfør hovedhandlingen og sammenlign med forrige tilstand.",
  "about.tools":"Gir enhetsoppdagelse, portkontroller, traceroute og DNS-sammenligning for å bekrefte rekkevidde, finne bruddpunkter og undersøke oppklaringsforskjeller.\nTrinn: åpne modulen, kontroller nåværende data, utfør hovedhandlingen og sammenlign med forrige tilstand.",
  "about.monitor":"Prøvetaker gatewayforsinkelse og pakketap over tid og lagrer trender og varsler. Nyttig for periodiske tregheter og ustabile lenker.\nTrinn: åpne modulen, kontroller nåværende data, utfør hovedhandlingen og sammenlign med forrige tilstand.\nSett kontinuerlig overvåking på pause eller fortsett den fra Overvåking-overskriften. «Mål nå» forblir tilgjengelig mens overvåkingen er satt på pause.",
  "about.security":"Sjekker brannmur, eksponerte lytteporter og risikable tjenester, og viser status for ekstern tunnel slik at du kan gjennomgå angrepsflaten.\nTrinn: åpne modulen, kontroller nåværende data, utfør hovedhandlingen og sammenlign med forrige tilstand.",
  "about.snapshots":"Lagrer nettverkskonfigurasjonsøyeblikksbilder, sammenligner forskjeller og støtter tilbakerulling før eller etter reparasjon som sikkerhet ved endringer.\nTrinn: åpne modulen, kontroller nåværende data, utfør hovedhandlingen og sammenlign med forrige tilstand.",
  "about.history":"Samler diagnose- og reparasjonshistorikk slik at du kan følge endringer i tall, feil, utførte handlinger og varighet ved senere gjennomgang.\nTrinn: åpne modulen, kontroller nåværende data, utfør hovedhandlingen og sammenlign med forrige tilstand.\nVedlikehold: fjern en enkelt post med “Slett”, eller bruk “Tøm alle” etter bekreftelse. Disse handlingene sletter ikke sikkerhetsloggen.\nHver rad kan laste ned diagnose- eller reparasjonsloggen som ble lagret da.",
  "about.settings":"Konfigurerer språk, tema, reparasjonstillatelser, planlagte kontroller og relaterte innstillinger. Om-siden viser versjon og utviklingsinformasjon.\nTrinn: åpne modulen, kontroller nåværende data, utfør hovedhandlingen og sammenlign med forrige tilstand.",
  "about.modulesHint":"Velg en modul for å utvide beskrivelse og trinn. Velg igjen for å skjule den. Lang tekst brytes uavhengig.",
  "about.aboutGuide":"Se appnavn, versjon, arkitektur, utvikler og utgiver. Start her når du bekrefter installert versjon eller undersøker en oppgradering. Utvid modulene for bruksområder og trinn.",
