  "if.up":"Upp",
  "if.down":"Nere",
  "nav.about":"Om",
  "about.title":"Om",
  "about.app":"Appnamn",
  "about.developer":"Utvecklare",
  "about.publisher":"Utgivare",
  "about.intro":"NetCheck diagnostiserar och reparerar nätverksproblem i TOS 7. Den granskar gränssnitt, isolerar anslutningsfel, kontrollerar DNS, TNAS.online och DDNS, mäter bandbredd och sparar historik så att du kan avgöra om problemet ligger på NAS:en, i LAN:t eller på internet.",
  "about.modules":"Modulguide",
  "about.dashboard":"Sammanfattar hälsopoäng, öppna ärenden, statuslampor och gränssnittsviktigheter så att du kan bedöma nätverket och starta en fullständig diagnos.\nSteg: öppna modulen, kontrollera aktuella data, kör huvudåtgärden och jämför med föregående tillstånd.",
  "about.interfaces":"Visar alla fysiska, virtuella, OVS- och tunnelgränssnitt med adresser, hastighet, läge, MAC och andra driftdata. Välj en rad för detaljer.\nSteg: öppna modulen, kontrollera aktuella data, kör huvudåtgärden och jämför med föregående tillstånd.\nSystemets loopback-gränssnitt är dolt eftersom det är internt och inte en LAN-/WAN-väg.\nLänkhastigheten förhandlas av nätverkskortet och är teoretisk länkkapacitet, inte uppmätt genomströmning. Använd ett bandbreddstest för genomströmning.",
  "about.diagnose":"Kör hela kontrollsviten och grupperar resultat som godkänt, varning, fel eller inte tillämpligt. Exportera en rapport eller följ guidad reparation.\nSteg: öppna modulen, kontrollera aktuella data, kör huvudåtgärden och jämför med föregående tillstånd.",
  "about.tools":"Erbjuder enhetsidentifiering, portkontroller, traceroute och DNS-jämförelse för att bekräfta nåbarhet, hitta brytpunkter och undersöka skillnader i uppslag.\nSteg: öppna modulen, kontrollera aktuella data, kör huvudåtgärden och jämför med föregående tillstånd.",
  "about.monitor":"Samplar gatewayfördröjning och paketförlust över tid och sparar trender och varningar. Användbart för intermittenta långsammare perioder och ostabila länkar.\nSteg: öppna modulen, kontrollera aktuella data, kör huvudåtgärden och jämför med föregående tillstånd.\nPausa eller återuppta kontinuerlig övervakning från Övervakningsrubriken. ”Mät nu” är tillgängligt även när övervakningen pausats.",
  "about.security":"Kontrollerar brandvägg, exponerade lyssningsportar och högrisktjänster samt visar status för fjärrtunneln så att du kan granska attackytan.\nSteg: öppna modulen, kontrollera aktuella data, kör huvudåtgärden och jämför med föregående tillstånd.",
  "about.snapshots":"Sparar ögonblicksbilder av nätverkskonfiguration, jämför skillnader och stöder återställning före eller efter reparation som ett säkerhetsnät för ändringar.\nSteg: öppna modulen, kontrollera aktuella data, kör huvudåtgärden och jämför med föregående tillstånd.",
  "about.history":"Samlar diagnostik- och reparationshistorik så att du kan följa poängförändringar, fel, utförda åtgärder och varaktighet vid senare granskning.\nSteg: öppna modulen, kontrollera aktuella data, kör huvudåtgärden och jämför med föregående tillstånd.\nUnderhåll: ta bort en enskild post med ”Ta bort” eller använd ”Rensa allt” efter bekräftelse. Dessa åtgärder raderar inte säkerhetsloggen.\nVarje rad kan ladda ner den diagnos- eller reparationslogg som sparades då.",
  "about.settings":"Konfigurerar språk, tema, reparationsrättigheter, schemalagda kontroller och relaterade inställningar. Om-sidan visar version och utvecklingsinformation.\nSteg: öppna modulen, kontrollera aktuella data, kör huvudåtgärden och jämför med föregående tillstånd.",
  "about.modulesHint":"Välj en modul för att expandera beskrivning och steg. Välj igen för att komprimera. Lång text radbryts oberoende.",
  "about.aboutGuide":"Se appnamn, version, arkitektur, utvecklare och utgivare. Börja här när du bekräftar installerad version eller undersöker en uppgradering. Expandera modulerna för användningsområden och steg.",
  "fix.dnsServers":"DNS-servrar (kommaseparerade)",
