  "nav.about":"Over",
  "about.title":"Over",
  "about.app":"Appnaam",
  "about.developer":"Ontwikkelaar",
  "about.publisher":"Uitgever",
  "about.intro":"NetCheck diagnosticeert en herstelt netwerkproblemen in TOS 7. Het inspecteert interfaces, isoleert verbindingsfouten, controleert DNS, TNAS.online en DDNS, meet bandbreedte en bewaart historie, zodat je kunt zien of het probleem bij de NAS, het LAN of internet ligt.",
  "about.modules":"Modulehandleiding",
  "about.dashboard":"Vat de healthscore, open problemen, statuslampjes en interface hoogtepunten samen zodat je de netwerktoestand kunt beoordelen en een volledige diagnose kunt starten.\nStappen: open de module, controleer huidige gegevens, voer de hoofdactie uit en vergelijk met de vorige toestand.",
  "about.interfaces":"Toont alle fysieke, virtuele, OVS- en tunnelinterfaces met adressen, snelheid, modus, MAC en andere runtimegegevens. Kies een rij voor details.\nStappen: open de module, controleer huidige gegevens, voer de hoofdactie uit en vergelijk met de vorige toestand.\nHet loopback-interface van het systeem is verborgen omdat het intern is en geen LAN/WAN-pad vormt.\nDe linksnelheid wordt door de NIC onderhandeld en is een theoretische linkmogelijkheid, geen gemeten doorvoer. Gebruik voor doorvoer een bandbreedtest.",
  "about.diagnose":"Voert de volledige controlesuite uit en groepeert resultaten als geslaagd, waarschuwing, fout of niet van toepassing. Exporteer een rapport of volg begeleide reparatie.\nStappen: open de module, controleer huidige gegevens, voer de hoofdactie uit en vergelijk met de vorige toestand.",
  "about.tools":"Biedt apparaatdetectie, poortchecks, traceroute en DNS-vergelijking om bereikbaarheid te controleren, breekpunten te vinden en verschil in resolving te onderzoeken.\nStappen: open de module, controleer huidige gegevens, voer de hoofdactie uit en vergelijk met de vorige toestand.",
  "about.monitor":"Bemonstert gatewaylatentie en pakketverlies over tijd en bewaart trends en waarschuwingen. Nuttig voor periodieke vertragingen en instabiele links.\nStappen: open de module, controleer huidige gegevens, voer de hoofdactie uit en vergelijk met de vorige toestand.\nPauzeer of hervat continue monitoring vanuit de kop Monitoring. „Nu meten” blijft beschikbaar wanneer monitoring gepauzeerd is.",
  "about.security":"Controleert firewall, blootgestelde luisterpoorten en riskantere services en toont de status van de externe tunnel om het aanvalsoppervlak te beoordelen.\nStappen: open de module, controleer huidige gegevens, voer de hoofdactie uit en vergelijk met de vorige toestand.",
  "about.snapshots":"Bewaart netwerkconfiguratie snapshots, vergelijkt verschillen en ondersteunt rollback voor of na reparatie als vangnet voor wijzigingen.\nStappen: open de module, controleer huidige gegevens, voer de hoofdactie uit en vergelijk met de vorige toestand.",
  "about.history":"Centraliseert diagnose- en reparatiehistorie zodat je scorewijzigingen, fouten, uitgevoerde acties en duur later kunt nalezen.\nStappen: open de module, controleer huidige gegevens, voer de hoofdactie uit en vergelijk met de vorige toestand.\nBeheer: verwijder één record met “Verwijderen” of gebruik na bevestiging “Alles wissen”. Deze acties verwijderen het beveiligingslogboek niet.\nElke rij kan het toen opgeslagen diagnose- of reparatielogboek downloaden.",
  "about.settings":"Configureert taal, thema, herstelrechten, geplande controles en gerelateerde voorkeuren. De Over-pagina toont versie- en ontwikkelinformatie.\nStappen: open de module, controleer huidige gegevens, voer de hoofdactie uit en vergelijk met de vorige toestand.",
  "about.modulesHint":"Kies een module om de beschrijving en stappen uit te klappen. Kies opnieuw om in te klappen. Lange tekst breekt onafhankelijk af.",
  "about.aboutGuide":"Bekijk appnaam, versie, architectuur, ontwikkelaar en uitgever. Begin hier bij het controleren van de geïnstalleerde versie of onderzoeken van een upgrade. Vouw modules uit voor gebruiksscenario’s en stappen.",
