  "nav.about":"O aplikaci",
  "about.title":"O aplikaci",
  "about.app":"Název aplikace",
  "about.developer":"Vývojář",
  "about.publisher":"Vydavatel",
  "about.intro":"NetCheck diagnostikuje a opravuje síťové problémy v TOS 7. Kontroluje rozhraní, izoluje poruchy připojení, testuje DNS, TNAS.online a DDNS, měří propustnost a uchovává historii, aby bylo zřejmé, zda je problém na NAS, v LAN nebo na internetu.",
  "about.modules":"Průvodce moduly",
  "about.dashboard":"Shrnuje skóre stavu, otevřené problémy, stavové indikátory a klíčové údaje rozhraní, takže můžete posoudit síť a spustit úplnou diagnostiku.\nKroky: otevřete modul, zkontrolujte aktuální data, proveďte hlavní akci a porovnejte s předchozím stavem.",
  "about.interfaces":"Zobrazuje všechna fyzická, virtuální, OVS a tunelová rozhraní včetně adres, rychlosti, režimu, MAC a dalších provozních dat. Vyberte řádek pro podrobnosti.\nKroky: otevřete modul, zkontrolujte aktuální data, proveďte hlavní akci a porovnejte s předchozím stavem.\nSystémové rozhraní loopback je skryté, protože je interní a nejde o cestu LAN/WAN.\nRychlost spojení vyjednává síťová karta a představuje teoretickou kapacitu spojení, nikoli naměřenou propustnost. Pro propustnost použijte test šířky pásma.",
  "about.diagnose":"Spustí kompletní sadu kontrol a seskupí výsledky jako úspěch, varování, chybu nebo neplatné. Exportujte zprávu nebo postupujte podle řízené opravy.\nKroky: otevřete modul, zkontrolujte aktuální data, proveďte hlavní akci a porovnejte s předchozím stavem.",
  "about.tools":"Nabízí zjišťování zařízení, kontroly portů, traceroute a porovnání DNS pro ověření dostupnosti, nalezení bodů přerušení a analýzu rozdílů ve zpracování.\nKroky: otevřete modul, zkontrolujte aktuální data, proveďte hlavní akci a porovnejte s předchozím stavem.",
  "about.monitor":"Opakovaně měří zpoždění a ztrátu paketů brány, ukládá trendy a výstrahy. Pomáhá při občasném zpomalení a nestabilním spojení.\nKroky: otevřete modul, zkontrolujte aktuální data, proveďte hlavní akci a porovnejte s předchozím stavem.\nPrůběžné sledování lze pozastavit nebo obnovit v záhlaví Sledování. „Změřit nyní” zůstává dostupné i při pozastaveném sledování.",
  "about.security":"Kontroluje firewall, exponované naslouchající porty a rizikovější služby a zobrazuje stav vzdáleného tunelu pro přehled attack surface.\nKroky: otevřete modul, zkontrolujte aktuální data, proveďte hlavní akci a porovnejte s předchozím stavem.",
  "about.snapshots":"Ukládá snímky síťové konfigurace, porovnává rozdíly a podporuje obnovení před nebo po opravě jako pojistku pro změny.\nKroky: otevřete modul, zkontrolujte aktuální data, proveďte hlavní akci a porovnejte s předchozím stavem.",
  "about.history":"Sjednocuje historii diagnostik a oprav, takže lze později sledovat změny skóre, chyby, provedené akce a doby trvání.\nKroky: otevřete modul, zkontrolujte aktuální data, proveďte hlavní akci a porovnejte s předchozím stavem.\nSpráva: jeden záznam odstraníte tlačítkem „Odstranit“ nebo po potvrzení použijete „Vymazat vše“. Tyto akce nemažou bezpečnostní protokol.\nZ každého řádku lze stáhnout tehdy uložený protokol diagnostiky nebo opravy.",
  "about.settings":"Nastavuje jazyk, motiv, oprávnění k opravám, plánované kontroly a související předvolby. Stránka O aplikaci zobrazuje verzi a vývojářské údaje.\nKroky: otevřete modul, zkontrolujte aktuální data, proveďte hlavní akci a porovnejte s předchozím stavem.",
  "about.modulesHint":"Vyberte modul pro rozbalení popisu a kroků. Opětovným výběrem jej sbalíte. Dlouhý text se zalomí nezávisle.",
  "about.aboutGuide":"Zkontrolujte název, verzi, architekturu, vývojáře a vydavatele aplikace. Začněte zde při ověřování nainstalované verze nebo zkoumání upgradu. Rozbalte moduly pro scénáře a kroky.",
