  "nav.about":"Informacje",
  "about.title":"Informacje",
  "about.app":"Nazwa aplikacji",
  "about.developer":"Deweloper",
  "about.publisher":"Wydawca",
  "about.intro":"NetCheck diagnozuje i naprawia problemy sieciowe w TOS 7. Sprawdza interfejsy, zawęża awarie łączności, testuje DNS, TNAS.online i DDNS, mierzy przepustowość i przechowuje historię, aby wskazać, czy problem dotyczy NAS, sieci LAN czy internetu.",
  "about.modules":"Przewodnik modułów",
  "about.dashboard":"Podsumowuje wynik kondycji, otwarte problemy, diody stanu i najważniejsze dane interfejsów, aby ocenić sieć i uruchomić pełną diagnostykę.\nKroki: otwórz moduł, sprawdź bieżące dane, wykonaj główną czynność i porównaj z poprzednim stanem.",
  "about.interfaces":"Wyświetla wszystkie interfejsy fizyczne, wirtualne, OVS i tunele wraz z adresami, prędkością, trybem, MAC i innymi danymi. Wybierz wiersz, aby zobaczyć szczegóły.\nKroki: otwórz moduł, sprawdź bieżące dane, wykonaj główną czynność i porównaj z poprzednim stanem.\nInterfejs loopback systemu jest ukryty, ponieważ jest wewnętrzny i nie jest ścieżką LAN/WAN.\nSzybkość łącza jest negocjowana przez kartę sieciową i oznacza teoretyczną możliwość łącza, a nie zmierzony przekrój. Do przekroju użyj testu przepustowości.",
  "about.diagnose":"Uruchamia pełny zestaw sprawdzeń i grupuje wyniki jako zaliczone, ostrzeżenie, błąd lub nie dotyczy. Eksportuj raport lub wykonaj naprawę krok po kroku.\nKroki: otwórz moduł, sprawdź bieżące dane, wykonaj główną czynność i porównaj z poprzednim stanem.",
  "about.tools":"Zawiera wykrywanie urządzeń, testy portów, traceroute i porównanie DNS, aby sprawdzić dostępność, znaleźć punkty przerwania i zbadać różnice resolucji.\nKroki: otwórz moduł, sprawdź bieżące dane, wykonaj główną czynność i porównaj z poprzednim stanem.",
  "about.monitor":"Okresowo próbuje opóźnienie i utratę pakietów bramy, zapisując trendy i alerty. Przydatne przy sporadycznych spowolnieniach i niestabilnych łączach.\nKroki: otwórz moduł, sprawdź bieżące dane, wykonaj główną czynność i porównaj z poprzednim stanem.\nWstrzymaj lub wznów ciągłe monitorowanie z nagłówka Monitorowania. „Pobierz próbkę” pozostaje dostępne podczas wstrzymania.",
  "about.security":"Sprawdza zaporę, ekspozycję nasłuchujących portów i bardziej ryzykowne usługi oraz pokazuje stan zdalnego tunelu, aby przejrzeć powierzchnię ataku.\nKroki: otwórz moduł, sprawdź bieżące dane, wykonaj główną czynność i porównaj z poprzednim stanem.",
  "about.snapshots":"Zapisuje migawki konfiguracji sieci, porównuje różnice i umożliwia przywrócenie przed lub po naprawie jako zabezpieczenie zmian.\nKroki: otwórz moduł, sprawdź bieżące dane, wykonaj główną czynność i porównaj z poprzednim stanem.",
  "about.history":"Centralizuje historię diagnostyk i napraw, umożliwiając śledzenie zmian wyniku, błędów, wykonanych działań i czasów w późniejszej analizie.\nKroki: otwórz moduł, sprawdź bieżące dane, wykonaj główną czynność i porównaj z poprzednim stanem.\nZarządzanie: usuń pojedynczy wpis przyciskiem „Usuń” lub po potwierdzeniu użyj „Wyczyść wszystko”. Te działania nie usuwają dziennika zabezpieczeń.\nKażdy wiersz pozwala pobrać zapisany wówczas dziennik diagnostyki lub naprawy.",
  "about.settings":"Konfiguruje język, motyw, uprawnienia napraw, zaplanowane sprawdzenia i powiązane preferencje. Strona Informacje pokazuje wersję i dane rozwojowe.\nKroki: otwórz moduł, sprawdź bieżące dane, wykonaj główną czynność i porównaj z poprzednim stanem.",
  "about.modulesHint":"Wybierz moduł, aby rozwinąć opis i kroki. Wybierz ponownie, aby zwinąć. Długi tekst zawija się niezależnie.",
  "about.aboutGuide":"Sprawdź nazwę, wersję, architekturę, dewelopera i wydawcę aplikacji. Zacznij tutaj, aby potwierdzić zainstalowaną wersję lub zbadać aktualizację. Rozwiń moduły, aby zobaczyć scenariusze i kroki.",
