  "nav.about":"О приложении",
  "about.title":"О приложении",
  "about.app":"Название приложения",
  "about.developer":"Разработчик",
  "about.publisher":"Издатель",
  "about.intro":"NetCheck диагностирует и устраняет сетевые проблемы TOS 7. Он проверяет интерфейсы, локализует сбои связи, тестирует DNS, TNAS.online и DDNS, измеряет пропускную способность и сохраняет историю, помогая понять, где проблема: в NAS, LAN или интернете.",
  "about.modules":"Руководство по модулям",
  "about.dashboard":"Сводит воедино оценку состояния, открытые проблемы, индикаторы и ключевые сведения об интерфейсах, чтобы оценить сеть и запустить полную диагностику.\nШаги: откройте модуль, проверьте текущие данные, выполните основное действие и сравните с прежним состоянием.",
  "about.interfaces":"Показывает все физические, виртуальные, OVS и туннельные интерфейсы с адресами, скоростью, режимом, MAC и другими фактами. Выберите строку для подробностей.\nШаги: откройте модуль, проверьте текущие данные, выполните основное действие и сравните с прежним состоянием.\nСистемный loopback-интерфейс скрыт: он внутренний и не является трактом LAN/WAN.\nСкорость канала согласуется сетевой картой и означает теоретическую возможность канала, а не измеренную пропускную способность. Для измерения используйте тест пропускной способности.",
  "about.diagnose":"Запускает полный набор проверок и группирует результаты: успех, предупреждение, ошибка или неприменимо. Экспортируйте отчет или выполните восстановление по подсказкам.\nШаги: откройте модуль, проверьте текущие данные, выполните основное действие и сравните с прежним состоянием.",
  "about.tools":"Содержит обнаружение устройств, проверку портов, traceroute и сравнение DNS для проверки доступности, поиска точки обрыва и анализа различий в разрешении имен.\nШаги: откройте модуль, проверьте текущие данные, выполните основное действие и сравните с прежним состоянием.",
  "about.monitor":"Периодически измеряет задержку и потери пакетов до шлюза, сохраняя тренды и оповещения. Помогает при периодических замедлениях и нестабильной связи.\nШаги: откройте модуль, проверьте текущие данные, выполните основное действие и сравните с прежним состоянием.\nПриостановить или возобновить непрерывный мониторинг можно в заголовке раздела. «Измерить сейчас» доступно и во время паузы.",
  "about.security":"Проверяет брандмауэр, открытые слушающие порты и более рискованные службы, а также состояние удаленного туннеля, чтобы оценить поверхность атаки.\nШаги: откройте модуль, проверьте текущие данные, выполните основное действие и сравните с прежним состоянием.",
  "about.snapshots":"Сохраняет снимки сетевой конфигурации, сравнивает различия и поддерживает откат до или после восстановления как страховку при изменениях.\nШаги: откройте модуль, проверьте текущие данные, выполните основное действие и сравните с прежним состоянием.",
  "about.history":"Централизует историю диагностики и восстановления, позволяя отслеживать изменение оценки, ошибки, выполненные действия и длительность.\nШаги: откройте модуль, проверьте текущие данные, выполните основное действие и сравните с прежним состоянием.\nУправление: удаляйте отдельную запись кнопкой «Удалить» или после подтверждения используйте «Очистить всё». Эти действия не удаляют журнал безопасности.\nКаждая строка позволяет скачать сохранённый тогда журнал диагностики или восстановления.",
  "about.settings":"Настраивает язык, тему, права восстановления, плановые проверки и связанные параметры. На странице «О приложении» видны версия и сведения о разработке.\nШаги: откройте модуль, проверьте текущие данные, выполните основное действие и сравните с прежним состоянием.",
  "about.modulesHint":"Выберите модуль, чтобы раскрыть подробное описание и шаги. Повторный выбор свернёт его. Длинный текст переносится независимо.",
  "about.aboutGuide":"Проверьте название, версию, архитектуру, разработчика и издателя приложения. Начните здесь, если нужно подтвердить установленную версию или разобраться с обновлением. Раскройте модули для сценариев и шагов.",
  "fix.dnsServers":"DNS-серверы (через запятую)",
  "fix.gateway":"Адрес шлюза",
