  "about.intro":"NetCheck 是面向 TOS 7 的网络诊断与修复工具，用于查看网卡状态、定位连通性故障、检测 DNS、TNAS.online 与 DDNS、测量带宽并保存历史，帮助用户快速判断问题出在设备、局域网还是外网。",
  "about.modules":"模块说明",
  "about.dashboard":"用途：快速判断当前 NAS 的整体网络状况，并确认自己正在查看哪台设备。\n操作指引：先核对标题下方的 hostname、主 IP 和架构；再看健康分、待处理问题数量和网关、互联网、DNS、IPv6 状态灯。发现异常时点击“Run Check”发起完整诊断，或点击“View All”进入 Diagnose 查看细节。\n提示：分数只是汇总结果，具体根因应结合 Diagnose 的分组结果判断。",
  "about.interfaces":"用途：查看所有物理口、OVS 内口、虚拟口、隧道和 Docker 桥接口的运行事实。\n操作指引：从左侧进入 Interfaces；先看 State 是 Up 还是 Down，再核对 IPv4、速率、模式和 MAC。点击任意一行可展开该接口的详细字段。若某个物理口显示 Down，可检查网线、交换机端口或聚合配置。\n提示：Up/Down 表示接口运行状态，不等同于诊断结论 Pass/Fail。\n系统回环接口会在页面中隐藏；它只用于本机内部通信，不是 LAN/WAN 链路。\n链路速率来自网卡协商结果，表示理论链路能力，不等于实测吞吐量；如需吞吐量请使用带宽测试。",
  "about.diagnose":"用途：执行完整网络体检，并把问题定位到链路、IP、路由、DNS、外网、TOS 服务或传输层。\n操作指引：点击 Run Full Check；按钮内出现旋转图标时表示正在执行。完成后按 A–I 分组阅读 Pass、Warn、Fail 和 N/A，优先处理 Fail。需要留档时可 Export 报告；有 Fix 按钮的项目可按向导确认后修复。\n提示：DNS 或外网异常可能影响多个下游项目，先解决基础问题再复查。",
  "about.tools":"用途：做针对性排查，而不是每次都运行完整诊断。\n操作指引：设备发现点击 Scan 后查看 IP/MAC 和冲突提示；Port Check 填写主机与端口后点击 Check；Traceroute 输入目标并追踪断点；DNS Compare 输入域名比较本地与公共解析结果。输入不完整时页面会提示缺少字段。\n提示：端口不通但域名能解析时，优先检查防火墙、服务状态和端口转发。",
  "about.monitor":"用途：跟踪时延、丢包和告警，适合排查“有时慢、有时断”的问题。\n操作指引：先点击 Sample Now 获取当前样本，再用 7 天或 30 天范围查看平均丢包、RTT、最大丢包和趋势。Alert History 用于确认异常发生时间和频率。配置监控阈值后，持续采样能反映链路是否稳定。\n提示：偶发异常要看多次样本，不要只凭单次 ping 判断。\n持续监控可在监控中心顶部暂停或恢复；暂停后“立即采样”仍可手动采集一次。",
  "about.security":"用途：查看防火墙、监听端口暴露面、高风险服务和远程隧道状态。\n操作指引：进入 Security 后点击 Rescan 获取最新结果；先确认防火墙是否启用，再查看暴露端口和风险等级。远程隧道用于确认 TNAS.online 连接状态。发现高风险监听时，应确认对应服务是否必要，并在 TOS 中调整权限或访问来源。\n提示：安全建议应结合实际使用场景执行，不要盲目关闭业务服务。",
  "about.snapshots":"用途：在修改或修复网络配置前留存可对比、可回滚的安全点。\n操作指引：点击 Create 生成快照，并填写便于识别的备注；需要判断变更时打开 Diff 查看差异。Restore 会替换当前网络配置，执行前务必确认备注、时间和差异，并确保设备仍有可用的管理路径。\n提示：重大变更前先创建快照，不要只依赖自动快照。",
  "about.history":"用途：回看诊断与修复过程，判断问题是偶发、持续还是由某次变更引起。\n操作指引：切换诊断和修复历史；查看分数、失败数量、执行动作、结果和耗时。修复后分数仍下降时，可对比前后记录确认根因是否解除。需要反馈时可导出诊断报告并附上时间点。\n提示：历史记录不会替代当前扫描，最新状态仍以重新诊断为准确。\n记录管理：可单击单条记录的“删除”按钮；确认后也可使用“清空全部”。这些操作不会删除安全审计日志。\n每一条记录都可下载当时保存的诊断或修复日志。",
  "about.settings":"用途：调整界面、语言、主题和修复安全策略。\n操作指引：在 Settings 中选择语言和主题，界面会立即应用；修复模式与管理员确认用于控制高风险操作的执行方式。修改后按需保存或刷新。版本和架构已集中在 About 页面查看。\n提示：不确定修复影响时保持管理员确认开启。",
  "about.modulesHint":"选择一个模块可展开详细说明与操作指引；再次点击可收起。内容独立展开，长文本会自动换行。",
  "about.aboutGuide":"查看应用名称、版本、架构、开发者和发布者；需要确认安装版本或排查升级问题时先看这里。展开各模块可了解适用场景和基本操作。",
