  "nav.about":"關於",
  "about.title":"關於",
  "about.app":"應用名稱",
  "about.developer":"開發者",
  "about.publisher":"發佈者",
  "about.intro":"NetCheck 是面向 TOS 7 的網絡診斷與修復工具，用於查看網卡狀態、定位連線故障、檢測 DNS、TNAS.online 與 DDNS、測量頻寬並保存歷史，協助用戶快速判斷問題出在裝置、區域網絡還是外部網絡。",
  "about.modules":"模組說明",
  "about.dashboard":"用途：快速判斷目前 NAS 的整體網絡狀況，並確認自己正在查看哪台裝置。\n操作指引：先核對標題下方的 hostname、主 IP 與架構；再看健康分、待處理問題數量和網關、互聯網、DNS、IPv6 狀態燈。發現異常時點擊「Run Check」發起完整診斷，或點擊「View All」進入 Diagnose 查看細節。\n提示：分數只是匯總結果，實際根因應結合 Diagnose 的分組結果判斷。",
  "about.interfaces":"用途：查看所有物理埠、OVS 內埠、虛擬埠、隧道和 Docker 橋接埠的運行事實。\n操作指引：從左側進入 Interfaces；先看 State 是 Up 還是 Down，再核對 IPv4、速率、模式與 MAC。點擊任意一行可展開該介面的詳細欄位。若某個物理埠顯示 Down，可檢查網線、交換器埠或聚合設定。\n提示：Up/Down 表示介面運行狀態，不等同於診斷結論 Pass/Fail。\n系統回環介面會在頁面中隱藏；它只用於本機內部通信，不是 LAN/WAN 鏈路。\n鏈路速率來自網卡協商結果，表示理論鏈路能力，不等於實測吞吐量；如需吞吐量請使用頻寬測試。",
  "about.diagnose":"用途：執行完整網絡體檢，並把問題定位到鏈路、IP、路由、DNS、外部網絡、TOS 服務或傳輸層。\n操作指引：點擊 Run Full Check；按鈕內出現旋轉圖標時表示正在執行。完成後按 A–I 分組閱讀 Pass、Warn、Fail 和 N/A，優先處理 Fail。需要留檔時可 Export 報告；有 Fix 按鈕的項目可按嚮導確認後修復。\n提示：DNS 或外部網絡異常可能影響多個下游項目，先解決基礎問題再復查。",
  "about.tools":"用途：做針對性排查，而不是每次都運行完整診斷。\n操作指引：設備發現點擊 Scan 後查看 IP/MAC 與衝突提示；Port Check 填寫主機與端口後點擊 Check；Traceroute 輸入目標並追蹤斷點；DNS Compare 輸入域名比較本地與公共解析結果。輸入不完整時頁面會提示缺少欄位。\n提示：端口不通但域名能解析時，優先檢查防火牆、服務狀態與端口轉發。",
  "about.monitor":"用途：追蹤時延、丟包與告警，適合排查「有時慢、有時斷」的問題。\n操作指引：先點擊 Sample Now 取得目前樣本，再用 7 天或 30 天範圍查看平均丟包、RTT、最大丟包與趨勢。Alert History 用於確認異常發生時間和頻率。設定監控閾值後，持續取樣能反映鏈路是否穩定。\n提示：偶發異常要看多次樣本，不要只憑單次 ping 判斷。\n持續監控可在監控中心頂部暫停或恢復；暫停後「立即取樣」仍可手動採集一次。",
  "about.security":"用途：查看防火牆、監聽端口暴露面、高風險服務與遠端隧道狀態。\n操作指引：進入 Security 後點擊 Rescan 取得最新結果；先確認防火牆是否啟用，再查看暴露端口與風險等級。遠端隧道用於確認 TNAS.online 連接狀態。發現高風險監聽時，應確認對應服務是否必要，並在 TOS 中調整權限或訪問來源。\n提示：安全建議應結合實際使用場景執行，不要盲目關閉業務服務。",
  "about.snapshots":"用途：在修改或修復網絡設定前留存可比較、可回滾的安全點。\n操作指引：點擊 Create 生成快照，並填寫便於識別的備註；需要判斷變更時打開 Diff 查看差異。Restore 會替換目前網絡設定，執行前務必確認備註、時間與差異，並確保裝置仍有可用的管理路徑。\n提示：重大變更前先建立快照，不要只依賴自動快照。",
  "about.history":"用途：回看診斷與修復過程，判斷問題是偶發、持續還是由某次變更引起。\n操作指引：切換診斷與修復歷史；查看分數、失敗數量、執行動作、結果與耗時。修復後分數仍下降時，可比對前後記錄確認根因是否解除。需要反饋時可匯出診斷報告並附上時間點。\n提示：歷史記錄不會替代目前掃描，最新狀態仍以重新診斷為準確。\n記錄管理：可單擊單條記錄的「刪除」按鈕；確認後也可使用「清空全部」。這些操作不會刪除安全審計日誌。\n每一條記錄都可下載當時保存的診斷或修復日誌。",
  "about.settings":"用途：調整界面、語言、主題與修復安全策略。\n操作指引：在 Settings 中選擇語言與主題，界面會立即應用；修復模式與管理員確認用於控制高風險操作的執行方式。修改後按需儲存或重新整理。版本與架構已集中在 About 頁面查看。\n提示：不確定修復影響時保持管理員確認開啟。",
  "about.modulesHint":"選擇一個模組可展開詳細說明與操作指引；再次點擊可收起。內容獨立展開，長文字會自動換行。",
  "about.aboutGuide":"查看應用名稱、版本、架構、開發者和發佈者；需要確認安裝版本或排查升級問題時先看這裡。展開各模組可了解適用場景和基本操作。",
