  "nav.about":"概要",
  "about.title":"概要",
  "about.app":"アプリ名",
  "about.developer":"開発者",
  "about.publisher":"発行者",
  "about.intro":"NetCheck は TOS 7 のネットワーク問題を診断・修復します。インターフェースを確認し、接続障害を切り分け、DNS・TNAS.online・DDNSを検査して、帯域を測定し履歴を保存します。問題が NAS、LAN、インターネットのどこにあるか判断しやすくなります。",
  "about.modules":"モジュールガイド",
  "about.dashboard":"健康スコア、未解決の問題、状態ランプ、インターフェースの要点をまとめ、ネット全体の状態を把握して完全診断を開始できます。.\n手順：モジュールを開き、現在のデータを確認し、主要な操作を実行して、以前の状態と比較してください。",
  "about.interfaces":"物理・仮想・OVS・トンネルの全インターフェースを、アドレス、速度、モード、MACなどの実行情報とともに表示します。行を選ぶと詳細が見られます。.\n手順：モジュールを開き、現在のデータを確認し、主要な操作を実行して、以前の状態と比較してください。\nシステムの loopback インターフェースは内部用であり LAN/WAN 経路ではないため、表示しません。\nリンク速度は NIC によってネゴシエーションされた理論上のリンク能力であり、実測スループットではありません。スループットは帯域テストを使用してください。",
  "about.diagnose":"完全なチェックを実行し、結果を合格・警告・失敗・対象外でグループ化します。レポートをエクスポートしたり、ガイドに従って修復できます。.\n手順：モジュールを開き、現在のデータを確認し、主要な操作を実行して、以前の状態と比較してください。",
  "about.tools":"機器検出、ポートチェック、traceroute、DNS比較を提供し、到達性の確認、断点の特定、名前解決差の調査に使います。.\n手順：モジュールを開き、現在のデータを確認し、主要な操作を実行して、以前の状態と比較してください。",
  "about.monitor":"ゲートウェイの遅延とパケットロスを定期サンプリングし、傾向とアラートを保存します。断続的な低速化や不安定なリンクの追跡に適しています。.\n手順：モジュールを開き、現在のデータを確認し、主要な操作を実行して、以前の状態と比較してください。\n継続監視は監視画面の上部で一時停止／再開できます。一時停止中も「今すぐサンプル」は利用できます。",
  "about.security":"ファイアウォール、リッスンポートの公開、リスクの高いサービスを確認し、リモートトンネルの状態を表示して攻撃対象領域を確認できます。.\n手順：モジュールを開き、現在のデータを確認し、主要な操作を実行して、以前の状態と比較してください。",
  "about.snapshots":"ネットワーク設定のスナップショットを保存し、差分を比較して、修復前後のロールバックに対応します。変更時の安全策です。.\n手順：モジュールを開き、現在のデータを確認し、主要な操作を実行して、以前の状態と比較してください。",
  "about.history":"診断と修復の履歴を一元表示し、スコア変化、失敗項目、実行アクション、所要時間をあとで確認しやすくします。.\n手順：モジュールを開き、現在のデータを確認し、主要な操作を実行して、以前の状態と比較してください。\n管理：個別の記録は「削除」で、確認後に「すべて削除」で一括整理できます。これらの操作ではセキュリティ監査ログは削除されません。\n各行から、当時に保存した診断または修復のログをダウンロードできます。",
  "about.settings":"言語、テーマ、修復権限、予定チェックなどの設定を管理します。概要ページにはバージョンと開発情報が表示されます。.\n手順：モジュールを開き、現在のデータを確認し、主要な操作を実行して、以前の状態と比較してください。",
  "about.modulesHint":"モジュールを選ぶと詳細説明と手順が展開します。もう一度選ぶと折りたたまれます。長いテキストは独立して折り返されます。",
  "about.aboutGuide":"アプリ名、バージョン、アーキテクチャ、開発者、発行元を確認します。インストール済みバージョンの確認やアップグレード調査ではまずここを見ます。モジュールを展開すると用途と手順を確認できます。",
