  "if.up":"활성",
  "if.down":"비활성",
  "nav.about":"정보",
  "about.title":"정보",
  "about.app":"앱 이름",
  "about.developer":"개발자",
  "about.publisher":"게시자",
  "about.intro":"NetCheck는 TOS 7 네트워크 문제를 진단하고 복구합니다. 인터페이스를 점검하고 연결 문제를 좁히며 DNS, TNAS.online, DDNS를 확인하고 대역폭을 측정해 기록을 남깁니다. 문제가 NAS, LAN, 인터넷 중 어디에 있는지 파악하는 데 도움을 줍니다.",
  "about.modules":"모듈 안내",
  "about.dashboard":"건강 점수, 열린 문제, 상태 표시 등 인터페이스 요약을 보여 전체 네트워크 상태를 파악하고 전체 진단을 시작할 수 있습니다.\n단계: 모듈을 열고 현재 데이터를 확인한 뒤 주요 작업을 실행하고 이전 상태와 비교합니다.",
  "about.interfaces":"물리, 가상, OVS, 터널 인터페이스를 주소, 속도, 모드, MAC 등 실행 정보와 함께 나열합니다. 행을 선택하면 세부 정보를 볼 수 있습니다.\n단계: 모듈을 열고 현재 데이터를 확인한 뒤 주요 작업을 실행하고 이전 상태와 비교합니다.\n시스템 loopback 인터페이스는 내부용이고 LAN/WAN 경로가 아니므로 숨깁니다.\n링크 속도는 NIC가 협상한 이론적 링크 능력이며 실측 처리량이 아닙니다. 처리량은 대역폭 테스트를 사용하세요.",
  "about.diagnose":"전체 검사를 실행하고 통과, 경고, 실패, 해당 없음으로 결과를 묶습니다. 보고서를 내보내거나 안내에 따라 복구할 수 있습니다.\n단계: 모듈을 열고 현재 데이터를 확인한 뒤 주요 작업을 실행하고 이전 상태와 비교합니다.",
  "about.tools":"기기 검색, 포트 검사, traceroute, DNS 비교를 제공해 도달 가능성을 확인하고 끊어진 지점과 조회 차이를 분석합니다.\n단계: 모듈을 열고 현재 데이터를 확인한 뒤 주요 작업을 실행하고 이전 상태와 비교합니다.",
  "about.monitor":"게이트웨이 지연과 패킷 손실을 주기적으로 샘플링하고 추세 및 알림을 저장합니다. 간헐적 속도 저하와 불안정한 링크 추적에 유용합니다.\n단계: 모듈을 열고 현재 데이터를 확인한 뒤 주요 작업을 실행하고 이전 상태와 비교합니다.\n연속 모니터링은 모니터링 화면 상단에서 일시중지하거나 재개할 수 있습니다. 일시중지 중에도 “지금 측정”은 사용할 수 있습니다.",
  "about.security":"방화벽, 수신 대기 포트 노출, 위험도가 높은 서비스를 점검하고 원격 터널 상태를 보여 공격 표면을 확인할 수 있습니다.\n단계: 모듈을 열고 현재 데이터를 확인한 뒤 주요 작업을 실행하고 이전 상태와 비교합니다.",
  "about.snapshots":"네트워크 구성 스냅샷을 저장하고 차이를 비교하며 복구 전후 롤백을 지원해 변경 전 안전장치 역할을 합니다.\n단계: 모듈을 열고 현재 데이터를 확인한 뒤 주요 작업을 실행하고 이전 상태와 비교합니다.",
  "about.history":"진단 및 복구 기록을 한곳에서 보고 점수 변화, 실패 항목, 실행 작업, 소요 시간을 추적합니다.\n단계: 모듈을 열고 현재 데이터를 확인한 뒤 주요 작업을 실행하고 이전 상태와 비교합니다.\n관리: 개별 기록은 “삭제”로 제거하고, 확인 후 “모두 지우기”로 일괄 정리할 수 있습니다. 이 작업은 보안 감사 로그를 삭제하지 않습니다.\n각 행에서 당시 저장된 진단 또는 복구 로그를 다운로드할 수 있습니다.",
  "about.settings":"언어, 테마, 복구 권한, 예약 검사 등 환경설정을 관리합니다. 정보 페이지에서 버전과 개발 정보를 확인합니다.\n단계: 모듈을 열고 현재 데이터를 확인한 뒤 주요 작업을 실행하고 이전 상태와 비교합니다.",
  "about.modulesHint":"모듈을 선택하면 자세한 설명과 단계가 펼쳐집니다. 다시 선택하면 접힙니다. 긴 텍스트는 독립적으로 줄 바꿈됩니다.",
  "about.aboutGuide":"앱 이름, 버전, 아키텍처, 개발자, 게시자를 확인합니다. 설치된 버전을 확인하거나 업그레이드를 조사할 때 먼저 봅니다. 모듈을 펼치면 사용 사례와 단계를 확인할 수 있습니다.",
