  "nav.about":"Giới thiệu",
  "about.title":"Giới thiệu",
  "about.app":"Tên ứng dụng",
  "about.developer":"Nhà phát triển",
  "about.publisher":"Nhà xuất bản",
  "about.intro":"NetCheck chẩn đoán và sửa sự cố mạng trên TOS 7. Nó kiểm tra giao diện, cô lập lỗi kết nối, kiểm tra DNS, TNAS.online và DDNS, đo băng thông và lưu lịch sử, giúp xác định lỗi nằm trên NAS, LAN hay Internet.",
  "about.modules":"Hướng dẫn mô-đun",
  "about.dashboard":"Tóm tắt điểm sức khỏe, sự cố đang mở, đèn trạng thái và điểm chính của giao diện, giúp đánh giá tổng thể mạng và bắt đầu chẩn đoán đầy đủ.\nCác bước: mở mô-đun, kiểm tra dữ liệu hiện tại, chạy hành động chính, rồi so với trạng thái trước.",
  "about.interfaces":"Liệt kê mọi giao diện vật lý, ảo, OVS và đường hầm cùng địa chỉ, tốc độ, chế độ, MAC và dữ liệu thực tế. Chọn một dòng để xem chi tiết.\nCác bước: mở mô-đun, kiểm tra dữ liệu hiện tại, chạy hành động chính, rồi so với trạng thái trước.\nGiao diện loopback của hệ thống bị ẩn vì là đường nội bộ, không phải đường LAN/WAN.\nTốc độ liên kết do NIC thương lượng và biểu thị năng lực lý thuyết, không phải thông lượng đo được. Để đo thông lượng, hãy dùng kiểm tra băng thông.",
  "about.diagnose":"Chạy toàn bộ bộ kiểm tra và nhóm kết quả thành đạt, cảnh báo, lỗi hoặc không áp dụng. Xuất báo cáo hoặc làm theo hướng dẫn sửa chữa.\nCác bước: mở mô-đun, kiểm tra dữ liệu hiện tại, chạy hành động chính, rồi so với trạng thái trước.",
  "about.tools":"Cung cấp khám phá thiết bị, kiểm tra cổng, traceroute và so sánh DNS để xác minh khả năng kết nối, xác định điểm đứt và phân tích khác biệt phân giải.\nCác bước: mở mô-đun, kiểm tra dữ liệu hiện tại, chạy hành động chính, rồi so với trạng thái trước.",
  "about.monitor":"Lấy mẫu định kỳ độ trễ và mất gói đến gateway, lưu xu hướng và cảnh báo. Hữu ích khi mạng chậm theo từng giai đoạn hoặc liên kết không ổn định.\nCác bước: mở mô-đun, kiểm tra dữ liệu hiện tại, chạy hành động chính, rồi so với trạng thái trước.\nTạm dừng hoặc tiếp tục giám sát liên tục từ tiêu đề Giám sát. “Đo ngay” vẫn khả dụng khi giám sát bị tạm dừng.",
  "about.security":"Kiểm tra tường lửa, cổng đang lắng nghe bị lộ và dịch vụ rủi ro cao, hiển thị trạng thái đường hầm từ xa để rà soát bề mặt tấn công.\nCác bước: mở mô-đun, kiểm tra dữ liệu hiện tại, chạy hành động chính, rồi so với trạng thái trước.",
  "about.snapshots":"Lưu bản chụp cấu hình mạng, so sánh khác biệt và hỗ trợ rollback trước hoặc sau sửa chữa như phương án an toàn khi thay đổi.\nCác bước: mở mô-đun, kiểm tra dữ liệu hiện tại, chạy hành động chính, rồi so với trạng thái trước.",
  "about.history":"Tập trung lịch sử chẩn đoán và sửa chữa, giúp theo dõi biến động điểm, lỗi, hành động đã chạy và thời gian để xem lại.\nCác bước: mở mô-đun, kiểm tra dữ liệu hiện tại, chạy hành động chính, rồi so với trạng thái trước.\nQuản lý: hãy xóa từng bản ghi bằng “Xóa” hoặc dùng “Xóa tất cả” sau khi xác nhận. Những thao tác này không xóa nhật ký bảo mật.\nMỗi dòng có thể tải xuống nhật ký chẩn đoán hoặc sửa chữa đã lưu tại thời điểm đó.",
  "about.settings":"Cấu hình ngôn ngữ, giao diện, quyền sửa chữa, kiểm tra định kỳ và tùy chọn liên quan. Trang Giới thiệu hiển thị phiên bản và thông tin phát triển.\nCác bước: mở mô-đun, kiểm tra dữ liệu hiện tại, chạy hành động chính, rồi so với trạng thái trước.",
  "about.modulesHint":"Chọn một mô-đun để mở mô tả chi tiết và các bước. Chọn lại để thu gọn. Văn bản dài tự xuống dòng độc lập.",
  "about.aboutGuide":"Xem tên ứng dụng, phiên bản, kiến trúc, nhà phát triển và nhà xuất bản. Bắt đầu ở đây khi xác nhận phiên bản đã cài hoặc kiểm tra nâng cấp. Mở từng mô-đun để xem tình huống dùng và các bước.",
