  "nav.about":"Tentang",
  "about.title":"Tentang",
  "about.app":"Nama aplikasi",
  "about.developer":"Pengembang",
  "about.publisher":"Penerbit",
  "about.intro":"NetCheck mendiagnosis dan memperbaiki masalah jaringan TOS 7. Aplikasi memeriksa antarmuka, mempersempit gangguan konektivitas, menguji DNS, TNAS.online, dan DDNS, mengukur bandwidth, serta menyimpan riwayat untuk menentukan apakah masalah ada di NAS, LAN, atau internet.",
  "about.modules":"Panduan modul",
  "about.dashboard":"Meringkas skor kesehatan, masalah terbuka, lampu status, dan ringkasan antarmuka untuk menilai kondisi jaringan dan memulai diagnosis lengkap.\nLangkah: buka modul, periksa data saat ini, jalankan aksi utama, lalu bandingkan dengan kondisi sebelumnya.",
  "about.interfaces":"Menampilkan semua antarmuka fisik, virtual, OVS, dan tunnel beserta alamat, kecepatan, mode, MAC, dan data runtime lainnya. Pilih baris untuk detail.\nLangkah: buka modul, periksa data saat ini, jalankan aksi utama, lalu bandingkan dengan kondisi sebelumnya.\nAntarmuka loopback sistem disembunyikan karena bersifat internal dan bukan jalur LAN/WAN.\nLaju tautan dinegosiasikan oleh NIC dan menunjukkan kemampuan tautan teoretis, bukan throughput terukur. Gunakan uji bandwidth untuk throughput.",
  "about.diagnose":"Menjalankan rangkaian pemeriksaan lengkap dan mengelompokkan hasil sebagai lulus, peringatan, gagal, atau tidak berlaku. Ekspor laporan atau ikuti perbaikan terpandu.\nLangkah: buka modul, periksa data saat ini, jalankan aksi utama, lalu bandingkan dengan kondisi sebelumnya.",
  "about.tools":"Menyediakan penemuan perangkat, pemeriksaan port, traceroute, dan perbandingan DNS untuk memverifikasi jangkauan, menemukan titik putus, dan menyelidiki perbedaan resolusi.\nLangkah: buka modul, periksa data saat ini, jalankan aksi utama, lalu bandingkan dengan kondisi sebelumnya.",
  "about.monitor":"Mengambil sampel latensi dan kehilangan paket gateway secara berkala, menyimpan tren dan peringatan. Berguna untuk perlambatan intermiten dan tautan tidak stabil.\nLangkah: buka modul, periksa data saat ini, jalankan aksi utama, lalu bandingkan dengan kondisi sebelumnya.\nJeda atau lanjutkan pemantauan berkelanjutan dari header Pemantauan. “Ukur sekarang” tetap tersedia saat pemantauan dijeda.",
  "about.security":"Memeriksa firewall, paparan port yang mendengarkan, dan layanan berisiko tinggi, serta menampilkan status tunnel jarak jauh untuk meninjau permukaan serangan.\nLangkah: buka modul, periksa data saat ini, jalankan aksi utama, lalu bandingkan dengan kondisi sebelumnya.",
  "about.snapshots":"Menyimpan snapshot konfigurasi jaringan, membandingkan perbedaan, dan mendukung rollback sebelum atau sesudah perbaikan sebagai pengaman perubahan.\nLangkah: buka modul, periksa data saat ini, jalankan aksi utama, lalu bandingkan dengan kondisi sebelumnya.",
  "about.history":"Memusatkan riwayat diagnosis dan perbaikan sehingga Anda dapat melacak perubahan skor, kegagalan, tindakan yang dijalankan, dan durasi untuk ditinjau.\nLangkah: buka modul, periksa data saat ini, jalankan aksi utama, lalu bandingkan dengan kondisi sebelumnya.\nPengelolaan: hapus satu catatan dengan “Hapus”, atau gunakan “Hapus Semua” setelah dikonfirmasi. Tindakan ini tidak menghapus log keamanan.\nSetiap baris dapat mengunduh log diagnosis atau perbaikan yang disimpan saat itu.",
  "about.settings":"Mengonfigurasi bahasa, tema, izin perbaikan, pemeriksaan terjadwal, dan preferensi terkait. Halaman Tentang menampilkan versi dan informasi pengembangan.\nLangkah: buka modul, periksa data saat ini, jalankan aksi utama, lalu bandingkan dengan kondisi sebelumnya.",
  "about.modulesHint":"Pilih modul untuk memperluas deskripsi dan langkahnya. Pilih lagi untuk menyempitkannya. Teks panjang terbungkus secara independen.",
  "about.aboutGuide":"Tinjau nama, versi, arsitektur, pengembang, dan penerbit aplikasi. Mulai di sini saat mengonfirmasi versi terpasang atau menyelidiki peningkatan. Perluas modul untuk kasus penggunaan dan langkahnya.",
